export type RP7<T1, T2, T3, T4, T5, T6, T7> = Readonly<[ROP<T1>, ROP<T2>, ROP<T3>, ROP<T4>, ROP<T5>, ROP<T6>, ROP<T7>]>;
export type RP8<T1, T2, T3, T4, T5, T6, T7, T8> = Readonly<[ROP<T1>, ROP<T2>, ROP<T3>, ROP<T4>, ROP<T5>, ROP<T6>, ROP<T7>, ROP<T8>]>;
